-- Function: public.fn_get_intelligence_planning_gaps
-- Backup generated on 2026-10-25 20:33:26

CREATE OR REPLACE FUNCTION public.fn_get_intelligence_planning_gaps(p_tenant_id uuid, p_org_id uuid, p_branch_id uuid, p_classroom_id uuid, p_today date, p_seven_days_out date)  RETURNS TABLE(classroom_id uuid, classroom_name character varying, branch_name character varying, upcoming_plans_count bigint)  LANGUAGE sql  STABLE AS $function$     SELECT          cl.id AS classroom_id,         cl.name AS classroom_name,         b.name AS branch_name,         COUNT(es.id) AS upcoming_plans_count     FROM classrooms cl     JOIN branches b ON cl.branch_id = b.id     LEFT JOIN experience_schedules es ON cl.id = es.classroom_id          AND es.tenant_id = p_tenant_id          AND es.scheduled_date BETWEEN p_today AND p_seven_days_out          AND es.status NOT IN ('Cancelled')     WHERE cl.tenant_id = p_tenant_id       AND b.organization_id = p_org_id       AND (p_branch_id IS NULL OR b.id = p_branch_id)       AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)       AND cl.is_active = true     GROUP BY cl.id, cl.name, b.name     HAVING COUNT(es.id) < 2     ORDER BY upcoming_plans_count ASC, cl.name; $function$ ;
